package com.library.server.service.impl;
import com.library.common.constant.RoleConstant; import com.library.common.exception.BusinessException; import com.library.common.model.LoginUser; import com.library.common.util.JwtUtil; import com.library.pojo.dto.LoginDTO; import com.library.pojo.entity.Admin; import com.library.pojo.entity.Reader; import com.library.pojo.vo.LoginVO; import com.library.pojo.vo.UserVO; import com.library.server.mapper.AdminMapper; import com.library.server.mapper.ReaderMapper; import com.library.server.service.AuthService; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service;
@Service public class AuthServiceImpl implements AuthService { private final AdminMapper adminMapper; private final ReaderMapper readerMapper; private final PasswordEncoder encoder; private final JwtUtil jwtUtil; public AuthServiceImpl(AdminMapper a,ReaderMapper r,PasswordEncoder e,JwtUtil j){adminMapper=a;readerMapper=r;encoder=e;jwtUtil=j;}
 public LoginVO login(LoginDTO dto){LoginUser user; UserVO responseUser; if(RoleConstant.ADMIN.equalsIgnoreCase(dto.role())){Admin a=adminMapper.findByUsername(dto.username()); if(a==null||a.getStatus()!=1||!encoder.matches(dto.password(),a.getPassword()))throw new BusinessException("账号或密码错误"); user=new LoginUser(a.getId(),a.getUsername(),a.getRealName(),RoleConstant.ADMIN); responseUser=new UserVO(a.getId(),a.getUsername(),a.getRealName(),RoleConstant.ADMIN);}else{Reader r=readerMapper.findByUsername(dto.username());if(r==null||r.getStatus()!=1||!encoder.matches(dto.password(),r.getPassword()))throw new BusinessException("账号或密码错误");user=new LoginUser(r.getId(),r.getUsername(),r.getRealName(),RoleConstant.READER); responseUser=new UserVO(r.getId(),r.getUsername(),r.getRealName(),RoleConstant.READER);}return new LoginVO(jwtUtil.createToken(user),responseUser);}
}
